const q = $json.query ?? {};
const unidade = String(q.unit ?? '').trim().toLowerCase();
const codigo = String(q.codigo ?? '').trim();
const decisao = String(q.decisao ?? '').trim().toUpperCase();

const unidades = {
  unidade: { nome: 'Unidade', tabelaId: 'SUBSTITUA_PELO_ID_DA_DATA_TABLE' },
};

if (!unidades[unidade]) throw new Error('Unidade inválida ou ausente.');
if (!codigo) throw new Error('Código da solicitação ausente.');
if (!['APROVADO', 'REPROVADO'].includes(decisao)) throw new Error('Decisão inválida ou ausente.');

return [{ json: {
  unidade,
  unidadeNome: unidades[unidade].nome,
  tabelaId: unidades[unidade].tabelaId,
  codigo,
  decisao,
} }];

const p = $('Código • Validar link de decisão').first().json;
const r = $input.first().json ?? {};
const esc = (v) => String(v ?? '')
  .replaceAll('&', '&amp;').replaceAll('<', '&lt;')
  .replaceAll('>', '&gt;').replaceAll('"', '&quot;')
  .replaceAll("'", '&#039;');

const encontrada = String(r.Codigo ?? '') === p.codigo;
if (!encontrada) {
  const html = '<!doctype html><html lang="pt-BR"><head><meta charset="utf-8">' +
    '<meta name="viewport" content="width=device-width,initial-scale=1">' +
    '<title>Solicitação não encontrada</title></head>' +
    '<body style="margin:0;background:#f2f4f7;font-family:Arial,sans-serif;padding:24px">' +
    '<main style="max-width:560px;margin:40px auto;background:#fff;padding:32px;border-radius:14px;text-align:center;' +
    'box-shadow:0 8px 28px rgba(16,24,40,.12)"><div style="font-size:44px;color:#b42318">!</div>' +
    '<h2 style="color:#b42318">Solicitação não encontrada</h2>' +
    '<p style="color:#667085">Confira o link recebido ou verifique se a solicitação ainda existe.</p></main></body></html>';
  return [{ json: { html } }];
}

const aprovando = p.decisao === 'APROVADO';
const cor = aprovando ? '#15803d' : '#b42318';
const fundo = aprovando ? '#f0fdf4' : '#fef3f2';
const titulo = aprovando ? 'Confirmar aprovação' : 'Confirmar recusa';
const urlPost = 'https://SEU-N8N.EXEMPLO.COM/webhook/registrar-decisao-he';
const formatarData = (valor) => {
  const data = new Date(valor);
  if (Number.isNaN(data.getTime())) return valor || '—';
  return new Intl.DateTimeFormat('pt-BR', {
    timeZone: 'America/Sao_Paulo', day: '2-digit', month: '2-digit', year: 'numeric'
  }).format(data);
};
const formatarHora = (valor) => {
  const data = new Date(valor);
  if (Number.isNaN(data.getTime())) return valor || '';
  return new Intl.DateTimeFormat('pt-BR', {
    timeZone: 'America/Sao_Paulo', hour: '2-digit', minute: '2-digit', hour12: false
  }).format(data);
};
const horario = [formatarHora(r.InicioHE), formatarHora(r.FimHE)].filter(Boolean).join(' - ');
const campos = [
  ['Unidade', p.unidadeNome], ['Código', r.Codigo],
  ['Colaborador', r.NomeColaborador], ['Matrícula', r.Matricula],
  ['Setor', r.Setor], ['Data', formatarData(r.DataHE)], ['Horário', horario],
  ['Tipo', r.TipoHE], ['Motivo', r.MotivoHE], ['Solicitante', r.Solicitante],
];
const linhas = campos.map(([k,v]) => '<tr><td style="padding:9px 4px;border-bottom:1px solid #eaecf0;color:#667085;' +
  'width:145px;vertical-align:top">' + esc(k) + '</td><td style="padding:9px 4px;border-bottom:1px solid #eaecf0;' +
  'color:#101828;font-weight:600">' + esc(v || '—') + '</td></tr>').join('');
const obrigatorio = aprovando ? '' : ' required';
const ajuda = aprovando ? 'Comentário opcional.' : 'Informe o motivo da recusa.';

const html = '<!doctype html><html lang="pt-BR"><head><meta charset="utf-8">' +
  '<meta name="viewport" content="width=device-width,initial-scale=1"><title>' + titulo + '</title></head>' +
  '<body style="margin:0;background:#f2f4f7;color:#101828;font-family:Arial,sans-serif;padding:24px 14px">' +
  '<main style="max-width:620px;margin:20px auto;background:#fff;border-radius:14px;overflow:hidden;' +
  'box-shadow:0 8px 28px rgba(16,24,40,.12)"><header style="padding:24px 28px;background:#07599b;color:#fff">' +
  '<div style="font-size:12px;font-weight:700;letter-spacing:1.3px;text-transform:uppercase;opacity:.85">Sua Empresa</div>' +
  '<h1 style="margin:6px 0 0;font-size:24px">' + titulo + '</h1></header><section style="padding:28px">' +
  '<div style="margin-bottom:22px;padding:16px;border-left:5px solid ' + cor + ';border-radius:8px;background:' + fundo +
  ';color:' + cor + ';font-weight:700">Deseja realmente ' + (aprovando ? 'aprovar' : 'recusar') +
  ' esta solicitação de hora extra?</div><table style="width:100%;border-collapse:collapse;margin-bottom:24px">' + linhas +
  '</table><form method="post" action="' + urlPost + '">' +
  '<input type="hidden" name="unit" value="' + esc(p.unidade) + '">' +
  '<input type="hidden" name="codigo" value="' + esc(p.codigo) + '">' +
  '<input type="hidden" name="decisao" value="' + esc(p.decisao) + '">' +
  '<label for="comentario" style="display:block;margin-bottom:7px;font-weight:700">Comentário</label>' +
  '<textarea id="comentario" name="comentario" maxlength="1000"' + obrigatorio +
  ' style="box-sizing:border-box;width:100%;min-height:100px;padding:12px;border:1px solid #d0d5dd;border-radius:8px;' +
  'font:14px Arial;resize:vertical"></textarea><p style="margin:7px 0 22px;color:#667085;font-size:12px">' + ajuda +
  '</p><div style="display:flex;gap:10px;justify-content:flex-end;flex-wrap:wrap">' +
  '<button type="button" onclick="history.back()" style="padding:12px 18px;border:1px solid #d0d5dd;border-radius:8px;' +
  'background:#fff;color:#344054;font-weight:700;cursor:pointer">Cancelar</button>' +
  '<button type="submit" style="padding:12px 18px;border:0;border-radius:8px;background:' + cor +
  ';color:#fff;font-weight:700;cursor:pointer">' + titulo + '</button></div></form></section></main></body></html>';

return [{ json: { html } }];

const b = $json.body ?? {};
const unidade = String(b.unit ?? '').trim().toLowerCase();
const codigo = String(b.codigo ?? '').trim();
const decisao = String(b.decisao ?? '').trim().toUpperCase();
const comentario = String(b.comentario ?? '').trim().slice(0, 1000);
const unidades = {
  unidade: { nome: 'Unidade', tabelaId: 'SUBSTITUA_PELO_ID_DA_DATA_TABLE' },
};
if (!unidades[unidade]) throw new Error('Unidade inválida ou ausente.');
if (!codigo) throw new Error('Código da solicitação ausente.');
if (!['APROVADO', 'REPROVADO'].includes(decisao)) throw new Error('Decisão inválida ou ausente.');
if (decisao === 'REPROVADO' && !comentario) throw new Error('Informe o motivo da recusa.');
return [{ json: {
  unidade, unidadeNome: unidades[unidade].nome,
  tabelaId: unidades[unidade].tabelaId, codigo, decisao, comentario,
} }];

const p = $('Código • Validar decisão recebida').first().json;
const atualizado = String($json.StatusAprovacao ?? '').toUpperCase() === p.decisao;
const cor = atualizado ? (p.decisao === 'APROVADO' ? '#15803d' : '#b42318') : '#b54708';
const titulo = atualizado ? (p.decisao === 'APROVADO' ? 'Solicitação aprovada' : 'Solicitação recusada') : 'Solicitação já processada';
const mensagem = atualizado
  ? 'A decisão foi registrada com sucesso para a unidade ' + p.unidadeNome + '.'
  : 'Nenhuma alteração foi realizada. A solicitação pode já ter sido decidida.';
const html = '<!doctype html><html lang="pt-BR"><head><meta charset="utf-8">' +
  '<meta name="viewport" content="width=device-width,initial-scale=1"><title>' + titulo + '</title></head>' +
  '<body style="margin:0;background:#f2f4f7;font-family:Arial,sans-serif;padding:24px">' +
  '<main style="max-width:560px;margin:40px auto;background:#fff;padding:34px;border-radius:14px;text-align:center;' +
  'box-shadow:0 8px 28px rgba(16,24,40,.12)"><div style="font-size:46px;color:' + cor + '">' +
  (atualizado ? '&#10003;' : '!') + '</div><h2 style="color:' + cor + '">' + titulo + '</h2>' +
  '<p style="color:#667085;line-height:1.5">' + mensagem + '</p>' +
  '<p style="color:#98a2b3;font-size:12px">Esta página já pode ser fechada.</p></main></body></html>';
return [{ json: { html } }];

const FUSO_HORARIO = 'America/Sao_Paulo';

const colunas = [
  'id',
  'Codigo',
  'PreenchidoEm',
  'Solicitante',
  'NomeColaborador',
  'Matricula',
  'Setor',
  'DataHE',
  'InicioHE',
  'FimHE',
  'TipoHE',
  'MotivoHE',
  'EmailStatus',
  'EmailEnviadoEm',
  'StatusAprovacao',
  'DecidioEm',
  'createdAt',
  'updatedAt'
];

const camposSomenteData = [
  'DataHE'
];

const camposDataHora = [
  'PreenchidoEm',
  'InicioHE',
  'FimHE',
  'EmailEnviadoEm',
  'DecidioEm',
  'createdAt',
  'updatedAt'
];

const formatarDataLocal = valor => {
  if (!valor) return '';

  const data = new Date(valor);

  if (Number.isNaN(data.getTime())) {
    return valor;
  }

  return new Intl.DateTimeFormat('sv-SE', {
    timeZone: FUSO_HORARIO,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit'
  }).format(data);
};

const formatarDataHoraLocal = valor => {
  if (!valor) return '';

  const data = new Date(valor);

  if (Number.isNaN(data.getTime())) {
    return valor;
  }

  return new Intl.DateTimeFormat('sv-SE', {
    timeZone: FUSO_HORARIO,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
    hourCycle: 'h23'
  }).format(data);
};

const normalizar = valor => {
  if (valor === null || valor === undefined) {
    return '';
  }

  return String(valor).trim();
};

const montarLinha = row => {
  const linha = {};

  for (const coluna of colunas) {
    linha[coluna] = row[coluna] ?? '';
  }

  for (const campo of camposSomenteData) {
    linha[campo] = formatarDataLocal(row[campo]);
  }

  for (const campo of camposDataHora) {
    linha[campo] = formatarDataHoraLocal(row[campo]);
  }

  return linha;
};

const origem = $('Data Table • Ler Unidade')
  .all()
  .map(item => item.json);

const destino = $('Sheets • Ler Unidade')
  .all()
  .map(item => item.json)
  .filter(row => row && Object.keys(row).length > 0);

const destinoPorCodigo = new Map();

for (const row of destino) {
  const codigo = normalizar(row.Codigo);

  if (codigo) {
    destinoPorCodigo.set(codigo, row);
  }
}

const linhasParaSincronizar = [];

for (const row of origem) {
  const codigo = normalizar(row.Codigo);

  if (!codigo) {
    throw new Error(
      'Foi encontrada uma linha sem Codigo na Data Table.'
    );
  }

  const linha = montarLinha(row);
  const linhaExistente = destinoPorCodigo.get(codigo);

  // Se ainda não existe na planilha, adiciona.
  if (!linhaExistente) {
    linhasParaSincronizar.push({ json: linha });
    continue;
  }

  // Se existe, envia somente quando algum campo mudou.
  const mudou = colunas.some(coluna => {
    const valorAtual = normalizar(linha[coluna]);
    const valorNaPlanilha = normalizar(linhaExistente[coluna]);

    return valorAtual !== valorNaPlanilha;
  });

  if (mudou) {
    linhasParaSincronizar.push({ json: linha });
  }
}

return linhasParaSincronizar;
